282	/****************************************************************************
283	 * Name: init_builtin_run
284	 *
285	 * Description:
286	 *   Execute the builtin command of Init, builtin App, or NSH builtin.
287	 *
288	 * Input Parameters:
289	 *   am   - Instance of Action Manager.
290	 *   argc - Argument count.
291	 *   argv - A pointer to an array of string arguments. The end of the array
292	 *          is indicated with a NULL entry.
293	 *
294	 * Returned Value:
295	 *   Returns 0 (for Init builtin) or a PID(for builtin App or NSH builtin) on
296	 *   success; Returns the negative value of errno on failure.
297	 ****************************************************************************/
298	
299	int init_builtin_run(FAR struct action_manager_s *am,
300	                     int argc, FAR char **argv)
301	{
302	  pid_t pid;
303	  size_t i;
304	  int ret;
305	
306	  for (i = 0; i < nitems(g_builtin); i++)
307	    {
308	      if (!strcmp(g_builtin[i].cmd, argv[0]))
309	        {
310	          if (argc < g_builtin[i].minargs || argc > g_builtin[i].maxargs)
311	            {
312	              init_err("executing command '%s': invalid argument", argv[0]);
313	              init_dump_args(argc, argv);
314	              return -EINVAL;
315	            }
316	
317	          init_info("executing command '%s'", argv[0]);
318	          return g_builtin[i].func(am, argc, argv);
319	        }
